boost::uuids::uuid Uuid( const char *pszText )
{
	return boost::uuids::string_generator()( pszText );
}

CVariant Flags( uint32_t nLow, uint32_t nHigh )
{
	const uint32_t flags[2] = { nLow, nHigh };
	return CVariant( flags, sizeof( flags ) );
}

// One database for the whole program, as in the editor: it is opened once on a
// copy of TestDB/data and closed at exit.
class CDatabaseEnvironment : public testing::Environment
{
public:
	static std::filesystem::path dir;

	void SetUp() override
	{
		const auto nStamp = std::chrono::steady_clock::now().time_since_epoch().count();
		dir = std::filesystem::temp_directory_path() / fmt::format( "obk2-libdb-test-{}", nStamp );
		std::filesystem::copy( NTestDB::GetDataDir(), dir, std::filesystem::copy_options::recursive );
		const std::string szDir = dir.generic_string() + "/";

		NVFS::SetMainVFS( NVFS::CreateWinVFS( szDir ) );
		NVFS::SetMainFileCreator( NVFS::CreateWinFileCreator( szDir ) );
		ASSERT_TRUE( NDb::OpenDatabase( NVFS::GetMainVFS(), NVFS::GetMainFileCreator(), NDb::DATABASE_MODE_EDITOR ) );
		for ( const char *pszFile : { "object.xdb", "object2.xdb", "Weapons/USSR/Heavy/A20.xdb", "Weapons/USSR/Light/PPSh.xdb" } )
		{
			EXPECT_TRUE( NDb::RegisterResourceFile( pszFile ) ) << pszFile;
		}
	}

	void TearDown() override
	{
		NDb::CloseDatabase();
		std::error_code ec;
		std::filesystem::remove_all( dir, ec );
	}
};

std::filesystem::path CDatabaseEnvironment::dir;

const testing::Environment *const pDatabaseEnvironment = testing::AddGlobalTestEnvironment( new CDatabaseEnvironment );

// A new MechUnit for each test, so that none depends on what another left.
class CEditorDatabase : public testing::Test
{
protected:
	CObj<NDb::IObjMan> pMan;
	NDb::SMechUnit *pUnit = nullptr;

	void SetUp() override
	{
		pMan = NDb::CreateNewObject( "MechUnit" );
		ASSERT_NE( pMan, nullptr );
		pUnit = dynamic_cast<NDb::SMechUnit *>( pMan->GetObject() );
		ASSERT_NE( pUnit, nullptr );
	}

	int GetSize( const std::string &szArray )
	{
		CVariant value;
		EXPECT_TRUE( pMan->GetValue( szArray, &value ) ) << szArray;
		return int( value );
	}

	void ExpectValue( const std::string &szName, const CVariant &expected )
	{
		CVariant value;
		ASSERT_TRUE( pMan->GetValue( szName, &value ) ) << szName;
		EXPECT_TRUE( value == expected ) << szName;
	}

	void SetAndExpect( const std::string &szName, const CVariant &value )
	{
		ASSERT_TRUE( pMan->SetValue( szName, value ) ) << szName;
		ExpectValue( szName, value );
	}
};

